import copy, json, runpy, tempfile
from pathlib import Path

def raises(kind, fn, *args):
    try:
        fn(*args)
    except kind:
        return
    raise AssertionError('Expected rejection')

import importlib.util
spec = importlib.util.spec_from_file_location('candidate','solution.py')
candidate = importlib.util.module_from_spec(spec); spec.loader.exec_module(candidate)
assert candidate.parse_record(' x = -2 ') == ('x',-2)
for bad in ('x=1=2','=3','x=no','x'):
    raises(ValueError,candidate.parse_record,bad)
assert candidate.sum_records(['a=1','a=2','b=-1']) == {'a':3,'b':-1}
raises(ValueError,candidate.sum_records,['a=1','bad'])
calls = []
original = candidate.parse_record
def tracked(line):
    calls.append(line)
    return original(line)
candidate.parse_record = tracked
assert candidate.sum_records(['z=2']) == {'z':2} and calls == ['z=2']

import copy, json, runpy, tempfile
