    raise AssertionError('Expected rejection')

transfer = runpy.run_path('solution.py')['transfer']
accounts = {'a':1000,'b':200}; ledger = {}
transfer(accounts,'a','b',100,'r1',ledger)
assert accounts == {'a':900,'b':300} and sum(accounts.values()) == 1200
before = copy.deepcopy((accounts,ledger))
transfer(accounts,'a','b',100,'r1',ledger)
assert (accounts,ledger) == before
for source,dest,cents,rid in [('a','b',101,'r1'),('a','b',True,'x'),('a','b',1.5,'x'),('a','b',0,'x'),('a','b',-1,'x'),('a','b',901,'x'),('a','a',1,'x'),('missing','b',1,'x'),('a','missing',1,'x')]:
    raises((ValueError,TypeError),transfer,accounts,source,dest,cents,rid,ledger)
    assert (accounts,ledger) == before
